alter table public.clients add column if not exists recruitment_fee_percent numeric check (recruitment_fee_percent > 0 and recruitment_fee_percent <= 100), add column if not exists payment_terms_days integer check (payment_terms_days between 1 and 120), add column if not exists rebate_terms text; create or replace function public.assert_job_publish_compliance() returns trigger language plpgsql set search_path=public as $$ declare cl public.clients%rowtype; co public.companies%rowtype; begin if new.status::text <> 'published' then return new; end if; select * into cl from public.clients where id=new.client_id and company_id=new.company_id; select * into co from public.companies where id=new.company_id; if co.legal_name is null or btrim(co.legal_name)='' or co.legal_address is null or btrim(co.legal_address)='' or co.privacy_email is null or btrim(co.privacy_email)='' then raise exception 'Agency legal identity and privacy contact must be configured before publishing vacancies'; end if; if cl.id is null or cl.terms_accepted_at is null or cl.terms_version is null or coalesce(btrim(cl.business_nature),'')='' or cl.recruitment_fee_percent is null or cl.payment_terms_days is null or coalesce(btrim(cl.rebate_terms),'')='' then raise exception 'Complete client terms, fee, payment and rebate terms before publishing vacancies'; end if; if new.application_mode <> 'register_interest' then if new.genuine_vacancy_confirmed_at is null or coalesce(btrim(new.client_instruction_reference),'')='' then raise exception 'A genuine client instruction must be evidenced before publication'; end if; if new.start_date is null or coalesce(btrim(new.duration_text),'')='' or coalesce(btrim(new.duties),'')='' or coalesce(btrim(new.work_days_hours),'')='' then raise exception 'Start date, duration, duties and days/hours are required'; end if; if coalesce(btrim(new.health_safety_risks),'')='' or coalesce(btrim(new.required_qualifications),'')='' or coalesce(btrim(new.expenses_text),'')='' then raise exception 'Health and safety, qualifications and expenses information are required'; end if; if coalesce(btrim(new.minimum_remuneration_text),'')='' or coalesce(btrim(new.pay_interval),'')='' or coalesce(btrim(new.notice_period),'')='' then raise exception 'Remuneration, pay interval and notice period are required'; end if; end if; return new; end $$;
